#!/usr/bin/env bash\nset -euo pipefail\n\nif [[ $# -lt 1 ]]; then\n  echo "usage: $0 /path/to/nession [output-dir]" >&2\n  exit 64\nfi\n\nROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"\nSOURCE_REPO="$(cd "$1" && pwd)"\nOUTPUT_DIR="${2:-$ROOT/research-runs/pilots}"\nEXP="$ROOT/docs/topics/agent-native-repository-architecture/research/experiments/nession-terminal-session-reconnect-2026-09"\n\nmkdir -p "$OUTPUT_DIR"\n\nrun_pilot() {\n  local task="$1"\n  local treatment="$2"\n  local require_resolver="$3"\n  local run_id="${task}-${treatment}-01"\n\n  echo "==> pilot ${task}/${treatment}"\n\n  set +e\n  python3 "$ROOT/scripts/ai-native-repo-experiment.py" \\n    --source-repo "$SOURCE_REPO" \\n    --task "$EXP/runner/manifests/${task}.json" \\n    --treatments "$EXP/runner/treatments.json" \\n    --treatment "$treatment" \\n    --attempt 1 \\n    --setup-cmd 'cd web && npm ci' \\n    --agent-cmd "python3 '$ROOT/scripts/ai-native-codex-adapter.py' --model gpt-5.6-sol --effort high" \\n    --output-dir "$OUTPUT_DIR"\n  local runner_rc=$?\n  set -e\n\n  # 0 = task success, 2 = task semantic failure. Both can still validate pilot\n  # instrumentation. 3 means the harness itself failed.\n  if [[ "$runner_rc" -eq 3 ]]; then\n    echo "pilot runner infrastructure failed: $run_id" >&2\n    exit 3\n  fi\n\n  python3 "$ROOT/scripts/score-ai-native-run.py" \\n    --run-dir "$OUTPUT_DIR/$run_id" \\n    --gold "$EXP/runner/gold.json" \\n    --treatment "$treatment" \\n    --update-run-json \\n    > "$OUTPUT_DIR/$run_id/score.stdout.json"\n\n  local args=(--run-dir "$OUTPUT_DIR/$run_id")\n  if [[ "$require_resolver" == "yes" ]]; then\n    args+=(--require-resolver)\n  fi\n  python3 "$ROOT/scripts/validate-ai-native-pilot.py" "${args[@]}"\n}\n\nrun_pilot T05 A no\nrun_pilot T08 B no\nrun_pilot T20 C no\n\necho "All three instrumentation pilots passed."\n